const String kCurriculum = r'''{"v":1,"levels":{"معرفي":["تذكر","فهم","تطبيق","تحليل","تركيب","تقويم"],"مهاري":["تقليد","معالجة","إتقان","تكييف","ابتكار"],"وجداني":["استقبال","استجابة","تقدير","تنظيم","تمييز"]},"g":{"4":{"n":"الرابع الأساسي","tag":"Word وPublisher","w":[{"t":"الوحدة الثالثة: مفهوم برنامج Word وطرق فتحه","pl":{"goal":"أن يتعرف الطالب على البرنامج ويذكر استخدامه ويفتحه بصورة صحيحة.","res":"الحاسوب – الكتاب – جهاز العرض","str":"الشرح المبسط – العرض العملي / الحوار والمناقشة","ev":"أسئلة شفهية / وتطبيق عملي"},"s":[{"sub":"الحصة الأولى: الشرح والعرض العملي","goals":[{"t":"أن يتعرف الطالب على البرنامج ويذكر استخدامه ويفتحه بصورة صحيحة.","d":"معرفي","l":"تذكر"},{"t":"أن يذكر الطالب ثلاثة استخدامات لبرنامج Word.","d":"معرفي","l":"تذكر"}],"items":[{"c":"التمهيد: ماذا نستخدم لكتابة رسالة أو واجب على الحاسوب بدل الورقة والقلم؟","t":"يطرح على الطلاب السؤال: «ماذا نستخدم لكتابة رسالة أو واجب على الحاسوب بدل الورقة والقلم؟» ويستمع لإجاباتهم، ثم يربطها بموضوع الدرس: الوحدة الثالثة: مفهوم برنامج Word وطرق فتحه.","l":"يجيب عن السؤال ويذكر ما يعرفه سابقاً ويتوقع موضوع الدرس.","w":2,"s":"الحوار والمناقشة"},{"c":"• برنامج Word برنامج لمعالجة النصوص: يُستخدم لكتابة الرسائل والواجبات والتقارير وتنسيقها وطباعتها\n• طرق فتح البرنامج: (1) قائمة ابدأ ثم Word (2) البحث عن اسمه في شريط البحث (3) اختصار البرنامج على سطح المكتب\n• عند فتح البرنامج نختار «مستند فارغ» لنبدأ الكتابة","t":"يشرح النقاط المذكورة بالتتابع مستعيناً بالعرض العملي: يفتح المعلم Word أمام الطلاب بالطرق الثلاث على جهاز العرض ويقارن بينها، ثم يفتح مستنداً فارغاً.","l":"يتابع الشرح والعرض ويدوّن الملاحظات ويشارك بالأسئلة والأمثلة، وينفذ الخطوة بعد المعلم حيثما أمكن.","w":4,"s":"الشرح المبسط – العرض العملي"},{"c":"أسئلة التثبيت:\n• ما استخدامات برنامج Word؟\n• اذكر طريقتين لفتح البرنامج.\n• ماذا نختار عند فتح البرنامج لنبدأ الكتابة؟","t":"يطرح أسئلة التثبيت ويمرّ على الطلاب لمتابعة فهمهم وتصحيح الأخطاء، ثم يلخص أهم ما جاء في الدرس.","l":"يجيب عن الأسئلة ويلخص ما تعلمه بأسلوبه.","w":3,"s":"الأسئلة والأجوبة"}],"res":"الحاسوب – الكتاب – جهاز العرض","ev":"التقويم: أسئلة شفهية / وتطبيق عملي\nالواجب البيتي: كتابة ثلاثة استخدامات لبرنامج Word في الدفتر"},{"sub":"الحصة الثانية: التطبيق والتدريب","goals":[{"t":"أن يفتح الطالب برنامج Word بطريقتين مختلفتين.","d":"مهاري","l":"تقليد"},{"t":"أن يلتزم الطالب بتعليمات المعمل وآداب استخدام الجهاز.","d":"وجداني","l":"استجابة"}],"items":[{"c":"مراجعة سريعة لدرس الحصة السابقة:\n• برنامج Word برنامج لمعالجة النصوص: يُستخدم لكتابة الرسائل والواجبات والتقارير وتنسيقها وطباعتها\n• أسئلة المراجعة: ما استخدامات برنامج Word؟ — اذكر طريقتين لفتح البرنامج.","t":"يطرح أسئلة سريعة لاسترجاع ما سبق، ويصحح المفاهيم الخاطئة قبل البدء بالتطبيق.","l":"يتذكر ما تعلمه ويجيب ويصحح فهمه.","w":2,"s":"الأسئلة والأجوبة"},{"c":"المهمة التطبيقية: يفتح كل طالب Word بطريقتين مختلفتين على الأقل، ثم يفتح مستنداً فارغاً ويكتب اسمه في أول سطر ثم يغلق البرنامج.","t":"يوزع المهمة ويوضح معيار النجاح، ثم يتجول بين الطلاب للتوجيه ومعالجة الأخطاء الفردية.","l":"ينفذ المهمة بنفسه خطوة بخطوة، ويطلب المساعدة عند الحاجة.","w":4,"s":"الحوار والمناقشة"},{"c":"عرض عينات من أعمال الطلاب ومناقشتها وتقويمها وفق معيار النجاح.","t":"يختار نماذج من أعمال الطلاب ويناقشها مع الصف، ويسجل ملاحظات الأداء ويعالج الأخطاء الشائعة.","l":"يعرض عمله ويستمع إلى التغذية الراجعة ويصحح أخطاءه.","w":3,"s":"التقويم الذاتي والتغذية الراجعة"}],"res":"الحاسوب – الكتاب – جهاز العرض","ev":"التقويم: أسئلة شفهية / وتطبيق عملي\nالواجب البيتي: رسم أيقونة Word في الدفتر وكتابة خطوات فتح البرنامج"}]},{"t":"مكونات واجهة Word وقائمة ملف","pl":{"goal":"أن يتعرف الطالب على مكونات الواجهة ويميز وظائف قائمة ملف.","res":"الحاسوب – البرنامج – السبورة","str":"المشاهدة – العرض العملي / التطبيق الفردي","ev":"تحديد المكونات / تنفيذ الأوامر"},"s":[{"sub":"الحصة الأولى: الشرح والعرض العملي","goals":[{"t":"أن يتعرف الطالب على مكونات الواجهة ويميز وظائف قائمة ملف.","d":"معرفي","l":"فهم"},{"t":"أن يسمّي الطالب أربعة مكونات على الأقل من واجهة Word.","d":"معرفي","l":"تذكر"}],"items":[{"c":"التمهيد: عندما نفتح Word: ما الذي نراه في أعلى الشاشة؟ وأين نكتب؟","t":"يطرح على الطلاب السؤال: «عندما نفتح Word: ما الذي نراه في أعلى الشاشة؟ وأين نكتب؟» ويستمع لإجاباتهم، ثم يربطها بموضوع الدرس: مكونات واجهة Word وقائمة ملف.","l":"يجيب عن السؤال ويذكر ما يعرفه سابقاً ويتوقع موضوع الدرس.","w":2,"s":"الحوار والمناقشة"},{"c":"• مكونات الواجهة: شريط العنوان، الشريط وعلامات التبويب، منطقة الكتابة، شريط الحالة\n• قائمة «ملف» وأوامرها: جديد، فتح، حفظ، حفظ باسم، طباعة، إغلاق\n• علامة تبويب «الصفحة الرئيسية» وما فيها من أدوات الكتابة","t":"يشرح النقاط المذكورة بالتتابع مستعيناً بالعرض العملي: يشير المعلم إلى كل مكون على الشاشة المعروضة ويذكر وظيفته، ثم يفتح قائمة ملف ويستعرض أوامرها واحداً واحداً.","l":"يتابع الشرح والعرض ويدوّن الملاحظات ويشارك بالأسئلة والأمثلة، وينفذ الخطوة بعد المعلم حيثما أمكن.","w":4,"s":"المشاهدة – العرض العملي"},{"c":"أسئلة التثبيت:\n• ما اسم المنطقة التي نكتب فيها النص؟\n• ما وظيفة قائمة ملف؟\n• أين نجد شريط الحالة؟","t":"يطرح أسئلة التثبيت ويمرّ على الطلاب لمتابعة فهمهم وتصحيح الأخطاء، ثم يلخص أهم ما جاء في الدرس.","l":"يجيب عن الأسئلة ويلخص ما تعلمه بأسلوبه.","w":3,"s":"الأسئلة والأجوبة"}],"res":"الحاسوب – البرنامج – السبورة","ev":"التقويم: تحديد المكونات / تنفيذ الأوامر\nالواجب البيتي: رسم واجهة Word مبسطة في الدفتر وتسمية ثلاثة مكونات"},{"sub":"الحصة الثانية: التطبيق والتدريب","goals":[{"t":"أن ينفذ الطالب أمراً من قائمة ملف بصورة صحيحة.","d":"مهاري","l":"تقليد"},{"t":"أن يتعاون الطالب مع زميله في تحديد المكونات.","d":"وجداني","l":"استجابة"}],"items":[{"c":"مراجعة سريعة لدرس الحصة السابقة:\n• مكونات الواجهة: شريط العنوان، الشريط وعلامات التبويب، منطقة الكتابة، شريط الحالة\n• أسئلة المراجعة: ما اسم المنطقة التي نكتب فيها النص؟ — ما وظيفة قائمة ملف؟","t":"يطرح أسئلة سريعة لاسترجاع ما سبق، ويصحح المفاهيم الخاطئة قبل البدء بالتطبيق.","l":"يتذكر ما تعلمه ويجيب ويصحح فهمه.","w":2,"s":"الأسئلة والأجوبة"},{"c":"المهمة التطبيقية: يحدد الطالب أسماء المكونات على صورة واجهة Word في ورقة العمل، ثم ينفذ على جهازه أمرين من قائمة ملف (جديد ثم إغلاق).","t":"يوزع المهمة ويوضح معيار النجاح، ثم يتجول بين الطلاب للتوجيه ومعالجة الأخطاء الفردية.","l":"ينفذ المهمة بنفسه خطوة بخطوة، ويطلب المساعدة عند الحاجة.","w":4,"s":"التطبيق الفردي"},{"c":"عرض عينات من أعمال الطلاب ومناقشتها وتقويمها وفق معيار النجاح.","t":"يختار نماذج من أعمال الطلاب ويناقشها مع الصف، ويسجل ملاحظات الأداء ويعالج الأخطاء الشائعة.","l":"يعرض عمله ويستمع إلى التغذية الراجعة ويصحح أخطاءه.","w":3,"s":"التقويم الذاتي والتغذية الراجعة"}],"res":"الحاسوب – البرنامج – السبورة","ev":"التقويم: تحديد المكونات / تنفيذ الأوامر\nالواجب البيتي: كتابة ثلاثة أوامر من قائمة ملف مع وظيفة كل أمر"}]},{"t":"استخدام لوحة المفاتيح في كتابة النصوص","pl":{"goal":"أن يستخدم الطالب المفاتيح المناسبة لكتابة نص قصير.","res":"الحاسوب – لوحة المفاتيح","str":"التدريب العملي / التعلم بالممارسة","ev":"كتابة نص قصير"},"s":[{"sub":"الحصة الأولى: الشرح والعرض العملي","goals":[{"t":"أن يستخدم الطالب المفاتيح المناسبة لكتابة نص قصير.","d":"مهاري","l":"معالجة"},{"t":"أن يحدد الطالب وظيفة المفاتيح: Space وEnter وBackspace.","d":"معرفي","l":"تذكر"}],"items":[{"c":"التمهيد: كيف نكتب كلمة عربية ثم كلمة إنجليزية باستخدام لوحة المفاتيح نفسها؟","t":"يطرح على الطلاب السؤال: «كيف نكتب كلمة عربية ثم كلمة إنجليزية باستخدام لوحة المفاتيح نفسها؟» ويستمع لإجاباتهم، ثم يربطها بموضوع الدرس: استخدام لوحة المفاتيح في كتابة النصوص.","l":"يجيب عن السؤال ويذكر ما يعرفه سابقاً ويتوقع موضوع الدرس.","w":2,"s":"الحوار والمناقشة"},{"c":"• أجزاء لوحة المفاتيح: مفاتيح الحروف والأرقام والرموز ومفاتيح التحكم\n• المفاتيح المهمة: Space للمسافة، Enter لسطر جديد، Backspace وDelete للحذف، Shift للحروف الكبيرة والرموز\n• تبديل لغة الكتابة بين العربية والإنجليزية، ووضعية الجلوس الصحيحة","t":"يشرح النقاط المذكورة بالتتابع مستعيناً بالعرض العملي: يكتب المعلم جملة قصيرة ويبرز كل مفتاح عند استخدامه، ويبدّل اللغة بين العربية والإنجليزية، ثم يصحح خطأً مقصوداً بمفتاح Backspace.","l":"يتابع الشرح والعرض ويدوّن الملاحظات ويشارك بالأسئلة والأمثلة، وينفذ الخطوة بعد المعلم حيثما أمكن.","w":4,"s":"التدريب العملي"},{"c":"أسئلة التثبيت:\n• ما المفتاح الذي نستخدمه لترك مسافة بين الكلمات؟\n• كيف نحذف حرفاً كتبناه بالخطأ؟\n• كيف ننتقل إلى سطر جديد؟","t":"يطرح أسئلة التثبيت ويمرّ على الطلاب لمتابعة فهمهم وتصحيح الأخطاء، ثم يلخص أهم ما جاء في الدرس.","l":"يجيب عن الأسئلة ويلخص ما تعلمه بأسلوبه.","w":3,"s":"الأسئلة والأجوبة"}],"res":"الحاسوب – لوحة المفاتيح","ev":"التقويم: كتابة نص قصير\nالواجب البيتي: رسم لوحة المفاتيح في الدفتر وتلوين مفاتيح Space وEnter وBackspace"},{"sub":"الحصة الثانية: التطبيق والتدريب","goals":[{"t":"أن يكتب الطالب نصاً قصيراً بأقل عدد من الأخطاء باستخدام لوحة المفاتيح.","d":"مهاري","l":"إتقان"},{"t":"أن يلتزم الطالب بوضعية الجلوس الصحيحة أثناء الكتابة.","d":"وجداني","l":"استجابة"}],"items":[{"c":"مراجعة سريعة لدرس الحصة السابقة:\n• أجزاء لوحة المفاتيح: مفاتيح الحروف والأرقام والرموز ومفاتيح التحكم\n• أسئلة المراجعة: ما المفتاح الذي نستخدمه لترك مسافة بين الكلمات؟ — كيف نحذف حرفاً كتبناه بالخطأ؟","t":"يطرح أسئلة سريعة لاسترجاع ما سبق، ويصحح المفاهيم الخاطئة قبل البدء بالتطبيق.","l":"يتذكر ما تعلمه ويجيب ويصحح فهمه.","w":2,"s":"الأسئلة والأجوبة"},{"c":"المهمة التطبيقية: يكتب كل طالب نصاً قصيراً من سطرين (اسمه وصفه ومدرسته) مستخدماً Enter لسطر جديد وBackspace لتصحيح الأخطاء، ثم يبدّل اللغة ويكتب كلمتين بالإنجليزية.","t":"يوزع المهمة ويوضح معيار النجاح، ثم يتجول بين الطلاب للتوجيه ومعالجة الأخطاء الفردية.","l":"ينفذ المهمة بنفسه خطوة بخطوة، ويطلب المساعدة عند الحاجة.","w":4,"s":"التعلم بالممارسة"},{"c":"عرض عينات من أعمال الطلاب ومناقشتها وتقويمها وفق معيار النجاح.","t":"يختار نماذج من أعمال الطلاب ويناقشها مع الصف، ويسجل ملاحظات الأداء ويعالج الأخطاء الشائعة.","l":"يعرض عمله ويستمع إلى التغذية الراجعة ويصحح أخطاءه.","w":3,"s":"التقويم الذاتي والتغذية الراجعة"}],"res":"الحاسوب – لوحة المفاتيح","ev":"التقويم: كتابة نص قصير\nالواجب البيتي: كتابة ثلاث جمل قصيرة في الدفتر لنكتبها على الحاسوب في الحصة القادمة"}]},{"t":"تنسيق النصوص","pl":{"goal":"أن يطبق الطالب أدوات التنسيق الواردة في الكتاب.","res":"الحاسوب – برنامج Word – نص تدريبي","str":"العرض والتطبيق / التعلم بالممارسة","ev":"تنسيق نص / وفق المطلوب"},"s":[{"sub":"الحصة الأولى: الشرح والعرض العملي","goals":[{"t":"أن يطبق الطالب أدوات التنسيق الواردة في الكتاب.","d":"مهاري","l":"معالجة"},{"t":"أن يذكر الطالب ثلاث أدوات من أدوات تنسيق الخط.","d":"معرفي","l":"تذكر"}],"items":[{"c":"التمهيد: أمامنا نصّان لهما الكلام نفسه: أحدهما منسق والآخر عادي. أيهما أجمل ولماذا؟","t":"يطرح على الطلاب السؤال: «أمامنا نصّان لهما الكلام نفسه: أحدهما منسق والآخر عادي. أيهما أجمل ولماذا؟» ويستمع لإجاباتهم، ثم يربطها بموضوع الدرس: تنسيق النصوص.","l":"يجيب عن السؤال ويذكر ما يعرفه سابقاً ويتوقع موضوع الدرس.","w":2,"s":"الحوار والمناقشة"},{"c":"• تحديد النص بالفأرة قبل تنسيقه\n• أدوات الخط: نوع الخط، حجم الخط، لون الخط، غامق ومائل ومسطّر\n• أدوات الفقرة: المحاذاة (يمين، وسط، يسار)","t":"يشرح النقاط المذكورة بالتتابع مستعيناً بالعرض العملي: ينسق المعلم عنواناً أمام الطلاب: يحدده ثم يغيّر الخط والحجم واللون ويجعله غامقاً ويوسّطه، ويعرض النص قبل التنسيق وبعده.","l":"يتابع الشرح والعرض ويدوّن الملاحظات ويشارك بالأسئلة والأمثلة، وينفذ الخطوة بعد المعلم حيثما أمكن.","w":4,"s":"العرض والتطبيق"},{"c":"أسئلة التثبيت:\n• ماذا نفعل بالنص قبل أن ننسقه؟\n• كيف نجعل الكتابة غامقة؟\n• ما الأداة التي تضع العنوان في منتصف السطر؟","t":"يطرح أسئلة التثبيت ويمرّ على الطلاب لمتابعة فهمهم وتصحيح الأخطاء، ثم يلخص أهم ما جاء في الدرس.","l":"يجيب عن الأسئلة ويلخص ما تعلمه بأسلوبه.","w":3,"s":"الأسئلة والأجوبة"}],"res":"الحاسوب – برنامج Word – نص تدريبي","ev":"التقويم: تنسيق نص / وفق المطلوب\nالواجب البيتي: كتابة أسماء أدوات التنسيق التي تعلمناها ووظيفة كل منها"},{"sub":"الحصة الثانية: التطبيق والتدريب","goals":[{"t":"أن ينسق الطالب نصاً تنسيقاً صحيحاً وفق المطلوب.","d":"مهاري","l":"إتقان"},{"t":"أن يتذوق الطالب جمال النص المنسق ويقدّر أهمية التنسيق.","d":"وجداني","l":"تقدير"}],"items":[{"c":"مراجعة سريعة لدرس الحصة السابقة:\n• تحديد النص بالفأرة قبل تنسيقه\n• أسئلة المراجعة: ماذا نفعل بالنص قبل أن ننسقه؟ — كيف نجعل الكتابة غامقة؟","t":"يطرح أسئلة سريعة لاسترجاع ما سبق، ويصحح المفاهيم الخاطئة قبل البدء بالتطبيق.","l":"يتذكر ما تعلمه ويجيب ويصحح فهمه.","w":2,"s":"الأسئلة والأجوبة"},{"c":"المهمة التطبيقية: يفتح الطالب النص التدريبي، فينسق العنوان (خط، حجم كبير، لون، غامق، وسط) ثم ينسق الفقرة (حجم مناسب ومحاذاة مناسبة) وفق ورقة المطلوب.","t":"يوزع المهمة ويوضح معيار النجاح، ثم يتجول بين الطلاب للتوجيه ومعالجة الأخطاء الفردية.","l":"ينفذ المهمة بنفسه خطوة بخطوة، ويطلب المساعدة عند الحاجة.","w":4,"s":"التعلم بالممارسة"},{"c":"عرض عينات من أعمال الطلاب ومناقشتها وتقويمها وفق معيار النجاح.","t":"يختار نماذج من أعمال الطلاب ويناقشها مع الصف، ويسجل ملاحظات الأداء ويعالج الأخطاء الشائعة.","l":"يعرض عمله ويستمع إلى التغذية الراجعة ويصحح أخطاءه.","w":3,"s":"التقويم الذاتي والتغذية الراجعة"}],"res":"الحاسوب – برنامج Word – نص تدريبي","ev":"التقويم: تنسيق نص / وفق المطلوب\nالواجب البيتي: تلوين نموذج ورقي لعنوان منسق (خط كبير وغامق ووسط)"}]},{"t":"إدراج صورة وتنسيقها","pl":{"goal":"أن يدرج الطالب صورة ويعدل حجمها وموضعها.","res":"الحاسوب – Word – صور تدريبية","str":"العرض العملي / التعلم بالمهمة","ev":"تنفيذ مهمة / إدراج صورة"},"s":[{"sub":"الحصة الأولى: الشرح والعرض العملي","goals":[{"t":"أن يدرج الطالب صورة ويعدل حجمها وموضعها.","d":"مهاري","l":"معالجة"},{"t":"أن يذكر الطالب خطوات إدراج صورة بالترتيب.","d":"معرفي","l":"تذكر"}],"items":[{"c":"التمهيد: كيف نجعل واجبنا أو بطاقتنا أجمل بإضافة صورة تناسب موضوعها؟","t":"يطرح على الطلاب السؤال: «كيف نجعل واجبنا أو بطاقتنا أجمل بإضافة صورة تناسب موضوعها؟» ويستمع لإجاباتهم، ثم يربطها بموضوع الدرس: إدراج صورة وتنسيقها.","l":"يجيب عن السؤال ويذكر ما يعرفه سابقاً ويتوقع موضوع الدرس.","w":2,"s":"الحوار والمناقشة"},{"c":"• إدراج صورة: علامة التبويب «إدراج» ثم «صور» ثم اختيار الصورة من الجهاز\n• تغيير حجم الصورة بسحب مقابض الزوايا للحفاظ على نسبتها\n• تغيير موضع الصورة بسحبها أو باستخدام «التفاف النص»","t":"يشرح النقاط المذكورة بالتتابع مستعيناً بالعرض العملي: يدرج المعلم صورة من مجلد الصور التدريبية، ثم يغيّر حجمها بسحب الزاوية ويضعها في المكان المناسب بجانب النص.","l":"يتابع الشرح والعرض ويدوّن الملاحظات ويشارك بالأسئلة والأمثلة، وينفذ الخطوة بعد المعلم حيثما أمكن.","w":4,"s":"العرض العملي"},{"c":"أسئلة التثبيت:\n• أي علامة تبويب نستخدم لإدراج صورة؟\n• كيف نكبّر الصورة دون تشويهها؟\n• كيف نحرك الصورة إلى مكان آخر؟","t":"يطرح أسئلة التثبيت ويمرّ على الطلاب لمتابعة فهمهم وتصحيح الأخطاء، ثم يلخص أهم ما جاء في الدرس.","l":"يجيب عن الأسئلة ويلخص ما تعلمه بأسلوبه.","w":3,"s":"الأسئلة والأجوبة"}],"res":"الحاسوب – Word – صور تدريبية","ev":"التقويم: تنفيذ مهمة / إدراج صورة\nالواجب البيتي: كتابة خطوات إدراج صورة مرتبة في الدفتر"},{"sub":"الحصة الثانية: التطبيق والتدريب","goals":[{"t":"أن يدرج الطالب صورة ويضبط حجمها وموضعها.","d":"مهاري","l":"إتقان"},{"t":"أن يحرص الطالب على تنظيم عمله وجودة ترتيبه.","d":"وجداني","l":"استجابة"}],"items":[{"c":"مراجعة سريعة لدرس الحصة السابقة:\n• إدراج صورة: علامة التبويب «إدراج» ثم «صور» ثم اختيار الصورة من الجهاز\n• أسئلة المراجعة: أي علامة تبويب نستخدم لإدراج صورة؟ — كيف نكبّر الصورة دون تشويهها؟","t":"يطرح أسئلة سريعة لاسترجاع ما سبق، ويصحح المفاهيم الخاطئة قبل البدء بالتطبيق.","l":"يتذكر ما تعلمه ويجيب ويصحح فهمه.","w":2,"s":"الأسئلة والأجوبة"},{"c":"المهمة التطبيقية: يدرج الطالب من مجلد الصور التدريبية صورة مناسبة أسفل النص الذي كتبه، ويضبط حجمها وموضعها بحيث لا تغطي الكتابة، ثم يعرض عمله على المعلم.","t":"يوزع المهمة ويوضح معيار النجاح، ثم يتجول بين الطلاب للتوجيه ومعالجة الأخطاء الفردية.","l":"ينفذ المهمة بنفسه خطوة بخطوة، ويطلب المساعدة عند الحاجة.","w":4,"s":"التعلم بالمهمة"},{"c":"عرض عينات من أعمال الطلاب ومناقشتها وتقويمها وفق معيار النجاح.","t":"يختار نماذج من أعمال الطلاب ويناقشها مع الصف، ويسجل ملاحظات الأداء ويعالج الأخطاء الشائعة.","l":"يعرض عمله ويستمع إلى التغذية الراجعة ويصحح أخطاءه.","w":3,"s":"التقويم الذاتي والتغذية الراجعة"}],"res":"الحاسوب – Word – صور تدريبية","ev":"التقويم: تنفيذ مهمة / إدراج صورة\nالواجب البيتي: اختيار صورة مناسبة لموضوع «مدرستي» لنُدرجها في الحصة القادمة (وصفها أو رسمها)"}]},{"t":"مراجعة الوحدة الثالثة وتقويمها","pl":{"goal":"أن يوظف الطالب مهارات الكتابة والتنسيق وإدراج الصور.","res":"الحاسوب – ورقة عمل","str":"حل المشكلات / المراجعة","ev":"تقويم تحريري / وعملي"},"s":[{"sub":"الحصة الأولى: المراجعة","goals":[{"t":"أن يوظف الطالب مهارات الكتابة والتنسيق وإدراج الصور.","d":"مهاري","l":"إتقان"},{"t":"أن يحل الطالب ورقة العمل حلاً صحيحاً بنسبة لا تقل عن 80%.","d":"معرفي","l":"تطبيق"}],"items":[{"c":"التمهيد: من يتذكر أهم ما تعلمناه في الوحدة الثالثة؟ (فتح Word، الواجهة، الكتابة، التنسيق، الصور)","t":"يطرح السؤال: «من يتذكر أهم ما تعلمناه في الوحدة الثالثة؟ (فتح Word، الواجهة، الكتابة، التنسيق، الصور)» ويستعرض مع الطلاب خريطة المحتوى المراد مراجعته.","l":"يشارك بالإجابة ويسترجع ما تعلمه.","w":2,"s":"الحوار والمناقشة"},{"c":"نقاط المراجعة:\n• فتح البرنامج وواجهته وقائمة ملف\n• الكتابة بلوحة المفاتيح وتصحيح الأخطاء\n• تنسيق النص: الخط والحجم واللون والمحاذاة\n• إدراج الصورة وتغيير حجمها وموضعها","t":"يراجع النقاط بالتتابع، ثم ينفذ النشاط التالي: يوزع المعلم ورقة عمل (اختيار من متعدد، توصيل، وتسمية أجزاء الواجهة) ويناقش الإجابات بعد الحل.","l":"يشارك في المراجعة ويحل الأنشطة ويسجل ما يحتاج إلى معالجة.","w":4,"s":"حل المشكلات"},{"c":"أسئلة المراجعة:\n• ما وظيفة مفتاح Enter؟\n• كيف نغيّر لون الخط؟\n• كيف نحرك الصورة؟","t":"يطرح أسئلة المراجعة ويصحح الإجابات ويحدد نقاط الضعف لمعالجتها.","l":"يجيب عن الأسئلة ويدوّن أخطاءه لمعالجتها.","w":3,"s":"الأسئلة والأجوبة"}],"res":"الحاسوب – ورقة عمل","ev":"التقويم: تقويم تحريري / وعملي\nالواجب البيتي: مراجعة أدوات التنسيق من الكتاب استعداداً للتقويم"},{"sub":"الحصة الثانية: التقويم التطبيقي","goals":[{"t":"أن ينجز الطالب مهمة كتابة وتنسيق وإدراج صورة في مستند واحد.","d":"مهاري","l":"إتقان"},{"t":"أن يقيّم الطالب عمله بنفسه ويحدد نقاط القوة والضعف.","d":"وجداني","l":"تقدير"}],"items":[{"c":"مراجعة موجزة لأهم النقاط وتوضيح معايير التقويم.","t":"يذكّر الطلاب بأهم النقاط ويوضح معايير التقويم وزمنه.","l":"يستمع لمعايير التقويم ويستعد للتنفيذ.","w":2,"s":"الشرح الموجز"},{"c":"مهمة عملية: يكتب الطالب فقرة من ثلاثة أسطر عن «مدرستي»، وينسق عنوانها، ويدرج صورة ويضبط حجمها وموضعها، ثم يعرض عمله.","t":"يوزع المهمة أو ورقة الأسئلة ويراقب التنفيذ، ويسجل الدرجات وملاحظات الأداء.","l":"ينفذ المهمة بنفسه ويلتزم بالوقت والتعليمات.","w":4,"s":"المراجعة"},{"c":"مناقشة النتائج ومعالجة جوانب الضعف.","t":"يناقش النتائج مع الطلاب، ويقدم تغذية راجعة فردية ويحدد من يحتاج إلى تدريب علاجي.","l":"يستمع إلى التغذية الراجعة ويصحح أخطاءه ويحدد ما يحتاج إلى تحسين.","w":3,"s":"التقويم الذاتي والتغذية الراجعة"}],"res":"الحاسوب – ورقة عمل","ev":"التقويم: تقويم تحريري / وعملي\nالواجب البيتي: إكمال ورقة العمل إن لم تُنجز"}]},{"t":"الوحدة الرابعة: فتح برنامج الناشر Publisher","pl":{"goal":"أن يتعرف الطالب على استخدامات البرنامج ويفتحه.","res":"الحاسوب – برنامج الناشر – الكتاب","str":"الشرح / العرض العملي","ev":"أسئلة وملاحظة الأداء"},"s":[{"sub":"الحصة الأولى: الشرح والعرض العملي","goals":[{"t":"أن يتعرف الطالب على استخدامات البرنامج ويفتحه.","d":"معرفي","l":"فهم"},{"t":"أن يذكر الطالب ثلاثة أنواع من المنشورات يصممها بالناشر.","d":"معرفي","l":"تذكر"}],"items":[{"c":"التمهيد: كيف تُصنع بطاقات التهنئة والدعوات واللوحات الإعلانية على الحاسوب؟","t":"يطرح على الطلاب السؤال: «كيف تُصنع بطاقات التهنئة والدعوات واللوحات الإعلانية على الحاسوب؟» ويستمع لإجاباتهم، ثم يربطها بموضوع الدرس: الوحدة الرابعة: فتح برنامج الناشر Publisher.","l":"يجيب عن السؤال ويذكر ما يعرفه سابقاً ويتوقع موضوع الدرس.","w":2,"s":"الحوار والمناقشة"},{"c":"• برنامج الناشر (Publisher) برنامج لتصميم المنشورات: بطاقات، دعوات، لوحات، مطويات\n• طرق فتحه: قائمة ابدأ ثم Publisher، أو البحث عن اسمه\n• ما يظهر عند فتحه: صفحة القوالب التي نختار منها تصميماً","t":"يشرح النقاط المذكورة بالتتابع مستعيناً بالعرض العملي: يفتح المعلم Publisher بطريقتين ويعرض شاشة القوالب، ثم يعرض نماذج جاهزة لبطاقات ودعوات.","l":"يتابع الشرح والعرض ويدوّن الملاحظات ويشارك بالأسئلة والأمثلة، وينفذ الخطوة بعد المعلم حيثما أمكن.","w":4,"s":"الشرح"},{"c":"أسئلة التثبيت:\n• ما استخدامات برنامج الناشر؟\n• كيف نفتح البرنامج؟\n• ماذا يظهر لنا عند فتحه؟","t":"يطرح أسئلة التثبيت ويمرّ على الطلاب لمتابعة فهمهم وتصحيح الأخطاء، ثم يلخص أهم ما جاء في الدرس.","l":"يجيب عن الأسئلة ويلخص ما تعلمه بأسلوبه.","w":3,"s":"الأسئلة والأجوبة"}],"res":"الحاسوب – برنامج الناشر – الكتاب","ev":"التقويم: أسئلة وملاحظة الأداء\nالواجب البيتي: ذكر ثلاثة منشورات يمكن تصميمها بالناشر"},{"sub":"الحصة الثانية: التطبيق والتدريب","goals":[{"t":"أن يفتح الطالب برنامج الناشر ويستعرض القوالب المتاحة.","d":"مهاري","l":"تقليد"},{"t":"أن يُبدي الطالب اهتماماً بتصميم المنشورات.","d":"وجداني","l":"استقبال"}],"items":[{"c":"مراجعة سريعة لدرس الحصة السابقة:\n• برنامج الناشر (Publisher) برنامج لتصميم المنشورات: بطاقات، دعوات، لوحات، مطويات\n• أسئلة المراجعة: ما استخدامات برنامج الناشر؟ — كيف نفتح البرنامج؟","t":"يطرح أسئلة سريعة لاسترجاع ما سبق، ويصحح المفاهيم الخاطئة قبل البدء بالتطبيق.","l":"يتذكر ما تعلمه ويجيب ويصحح فهمه.","w":2,"s":"الأسئلة والأجوبة"},{"c":"المهمة التطبيقية: يفتح كل طالب Publisher وحده ويستعرض ثلاثة قوالب مختلفة ثم يغلق البرنامج.","t":"يوزع المهمة ويوضح معيار النجاح، ثم يتجول بين الطلاب للتوجيه ومعالجة الأخطاء الفردية.","l":"ينفذ المهمة بنفسه خطوة بخطوة، ويطلب المساعدة عند الحاجة.","w":4,"s":"العرض العملي"},{"c":"عرض عينات من أعمال الطلاب ومناقشتها وتقويمها وفق معيار النجاح.","t":"يختار نماذج من أعمال الطلاب ويناقشها مع الصف، ويسجل ملاحظات الأداء ويعالج الأخطاء الشائعة.","l":"يعرض عمله ويستمع إلى التغذية الراجعة ويصحح أخطاءه.","w":3,"s":"التقويم الذاتي والتغذية الراجعة"}],"res":"الحاسوب – برنامج الناشر – الكتاب","ev":"التقويم: أسئلة وملاحظة الأداء\nالواجب البيتي: رسم بطاقة تهنئة بسيطة في الدفتر"}]},{"t":"إنشاء بطاقة الناشر","pl":{"goal":"أن ينشئ الطالب بطاقة بسيطة باستخدام البرنامج.","res":"الحاسوب – برنامج الناشر – نماذج بطاقات","str":"التعلم القائم على المهمة / التطبيق العملي","ev":"إنشاء بطاقة أولية"},"s":[{"sub":"الحصة الأولى: الشرح والعرض العملي","goals":[{"t":"أن ينشئ الطالب بطاقة بسيطة باستخدام البرنامج.","d":"مهاري","l":"معالجة"},{"t":"أن يرتب الطالب خطوات إنشاء بطاقة ترتيباً صحيحاً.","d":"معرفي","l":"فهم"}],"items":[{"c":"التمهيد: لو أردنا بطاقة دعوة لحفل في المدرسة، ما الخطوات التي نتوقعها لإنشائها؟","t":"يطرح على الطلاب السؤال: «لو أردنا بطاقة دعوة لحفل في المدرسة، ما الخطوات التي نتوقعها لإنشائها؟» ويستمع لإجاباتهم، ثم يربطها بموضوع الدرس: إنشاء بطاقة الناشر.","l":"يجيب عن السؤال ويذكر ما يعرفه سابقاً ويتوقع موضوع الدرس.","w":2,"s":"الحوار والمناقشة"},{"c":"• اختيار نوع المنشور من القوالب: بطاقات\n• اختيار تصميم مناسب ثم الضغط على «إنشاء»\n• التعرف على صفحة البطاقة وعناصرها الجاهزة (نص وصورة)","t":"يشرح النقاط المذكورة بالتتابع مستعيناً بالعرض العملي: ينشئ المعلم بطاقة من قالب جاهز خطوة بخطوة، ويشير إلى النص والصورة الجاهزين فيها.","l":"يتابع الشرح والعرض ويدوّن الملاحظات ويشارك بالأسئلة والأمثلة، وينفذ الخطوة بعد المعلم حيثما أمكن.","w":4,"s":"التعلم القائم على المهمة"},{"c":"أسئلة التثبيت:\n• أي نوع من القوالب نختار لإنشاء بطاقة؟\n• ماذا نضغط بعد اختيار القالب؟\n• ما العناصر الموجودة في البطاقة الجاهزة؟","t":"يطرح أسئلة التثبيت ويمرّ على الطلاب لمتابعة فهمهم وتصحيح الأخطاء، ثم يلخص أهم ما جاء في الدرس.","l":"يجيب عن الأسئلة ويلخص ما تعلمه بأسلوبه.","w":3,"s":"الأسئلة والأجوبة"}],"res":"الحاسوب – برنامج الناشر – نماذج بطاقات","ev":"التقويم: إنشاء بطاقة أولية\nالواجب البيتي: كتابة خطوات إنشاء بطاقة مرتبة في الدفتر"},{"sub":"الحصة الثانية: التطبيق والتدريب","goals":[{"t":"أن ينشئ الطالب بطاقة من قالب جاهز.","d":"مهاري","l":"معالجة"},{"t":"أن يشارك الطالب زملاءه بعرض بطاقته.","d":"وجداني","l":"استجابة"}],"items":[{"c":"مراجعة سريعة لدرس الحصة السابقة:\n• اختيار نوع المنشور من القوالب: بطاقات\n• أسئلة المراجعة: أي نوع من القوالب نختار لإنشاء بطاقة؟ — ماذا نضغط بعد اختيار القالب؟","t":"يطرح أسئلة سريعة لاسترجاع ما سبق، ويصحح المفاهيم الخاطئة قبل البدء بالتطبيق.","l":"يتذكر ما تعلمه ويجيب ويصحح فهمه.","w":2,"s":"الأسئلة والأجوبة"},{"c":"المهمة التطبيقية: ينشئ الطالب بطاقة من قالب يختاره بنفسه ويتعرف على عناصرها دون تعديلها، ثم يعرض بطاقته على زميله.","t":"يوزع المهمة ويوضح معيار النجاح، ثم يتجول بين الطلاب للتوجيه ومعالجة الأخطاء الفردية.","l":"ينفذ المهمة بنفسه خطوة بخطوة، ويطلب المساعدة عند الحاجة.","w":4,"s":"التطبيق العملي"},{"c":"عرض عينات من أعمال الطلاب ومناقشتها وتقويمها وفق معيار النجاح.","t":"يختار نماذج من أعمال الطلاب ويناقشها مع الصف، ويسجل ملاحظات الأداء ويعالج الأخطاء الشائعة.","l":"يعرض عمله ويستمع إلى التغذية الراجعة ويصحح أخطاءه.","w":3,"s":"التقويم الذاتي والتغذية الراجعة"}],"res":"الحاسوب – برنامج الناشر – نماذج بطاقات","ev":"التقويم: إنشاء بطاقة أولية\nالواجب البيتي: اختيار مناسبة (عيد، نجاح، دعوة) لنصمم لها بطاقتنا"}]},{"t":"الكتابة على بطاقة التهنئة","pl":{"goal":"أن يضيف الطالب نصاً مناسباً ويرتب عناصر البطاقة.","res":"الحاسوب – برنامج الناشر – نماذج بطاقات","str":"العرض والتطبيق / التعلم بالممارسة","ev":"فحص البطاقة"},"s":[{"sub":"الحصة الأولى: الشرح والعرض العملي","goals":[{"t":"أن يضيف الطالب نصاً مناسباً ويرتب عناصر البطاقة.","d":"مهاري","l":"معالجة"},{"t":"أن يحدد الطالب كيف يُعدّل نصاً داخل مربع نص.","d":"معرفي","l":"فهم"}],"items":[{"c":"التمهيد: كيف نغيّر عبارة جاهزة على البطاقة إلى عبارة تهنئة نكتبها نحن؟","t":"يطرح على الطلاب السؤال: «كيف نغيّر عبارة جاهزة على البطاقة إلى عبارة تهنئة نكتبها نحن؟» ويستمع لإجاباتهم، ثم يربطها بموضوع الدرس: الكتابة على بطاقة التهنئة.","l":"يجيب عن السؤال ويذكر ما يعرفه سابقاً ويتوقع موضوع الدرس.","w":2,"s":"الحوار والمناقشة"},{"c":"• النقر داخل مربع النص ثم تحديد النص القديم وكتابة النص الجديد\n• تغيير الخط وحجمه ولونه كما في Word\n• تحريك مربعات النص والصور بالسحب وترتيبها بحيث لا تتداخل","t":"يشرح النقاط المذكورة بالتتابع مستعيناً بالعرض العملي: يكتب المعلم عبارة تهنئة داخل مربع النص ويغيّر خطها وحجمها، ثم يحرك مربع النص إلى موضع أفضل.","l":"يتابع الشرح والعرض ويدوّن الملاحظات ويشارك بالأسئلة والأمثلة، وينفذ الخطوة بعد المعلم حيثما أمكن.","w":4,"s":"العرض والتطبيق"},{"c":"أسئلة التثبيت:\n• كيف نكتب في مربع النص؟\n• كيف نغيّر حجم الخط؟\n• كيف نحرك مربع النص؟","t":"يطرح أسئلة التثبيت ويمرّ على الطلاب لمتابعة فهمهم وتصحيح الأخطاء، ثم يلخص أهم ما جاء في الدرس.","l":"يجيب عن الأسئلة ويلخص ما تعلمه بأسلوبه.","w":3,"s":"الأسئلة والأجوبة"}],"res":"الحاسوب – برنامج الناشر – نماذج بطاقات","ev":"التقويم: فحص البطاقة\nالواجب البيتي: كتابة عبارتي تهنئة مناسبتين لعيد أو نجاح"},{"sub":"الحصة الثانية: التطبيق والتدريب","goals":[{"t":"أن يكتب الطالب عبارة تهنئة وينسقها على البطاقة.","d":"مهاري","l":"إتقان"},{"t":"أن يحرص الطالب على اختيار عبارات لائقة ومهذبة.","d":"وجداني","l":"تقدير"}],"items":[{"c":"مراجعة سريعة لدرس الحصة السابقة:\n• النقر داخل مربع النص ثم تحديد النص القديم وكتابة النص الجديد\n• أسئلة المراجعة: كيف نكتب في مربع النص؟ — كيف نغيّر حجم الخط؟","t":"يطرح أسئلة سريعة لاسترجاع ما سبق، ويصحح المفاهيم الخاطئة قبل البدء بالتطبيق.","l":"يتذكر ما تعلمه ويجيب ويصحح فهمه.","w":2,"s":"الأسئلة والأجوبة"},{"c":"المهمة التطبيقية: يكتب الطالب عبارة تهنئة مناسبة على بطاقته، ويغيّر خطها وحجمها، ويرتب العناصر بحيث لا تتداخل.","t":"يوزع المهمة ويوضح معيار النجاح، ثم يتجول بين الطلاب للتوجيه ومعالجة الأخطاء الفردية.","l":"ينفذ المهمة بنفسه خطوة بخطوة، ويطلب المساعدة عند الحاجة.","w":4,"s":"التعلم بالممارسة"},{"c":"عرض عينات من أعمال الطلاب ومناقشتها وتقويمها وفق معيار النجاح.","t":"يختار نماذج من أعمال الطلاب ويناقشها مع الصف، ويسجل ملاحظات الأداء ويعالج الأخطاء الشائعة.","l":"يعرض عمله ويستمع إلى التغذية الراجعة ويصحح أخطاءه.","w":3,"s":"التقويم الذاتي والتغذية الراجعة"}],"res":"الحاسوب – برنامج الناشر – نماذج بطاقات","ev":"التقويم: فحص البطاقة\nالواجب البيتي: رسم مخطط لبطاقة يبين أماكن النص والصورة"}]},{"t":"تعديل ألوان المنشور","pl":{"goal":"أن يغير الطالب ألوان البطاقة بما يتناسب مع محتواها.","res":"الحاسوب – برنامج الناشر – نماذج تطبيقية","str":"العرض والتطبيق الفردي / التعلم بالممارسة","ev":"تقويم تنسيق الألوان"},"s":[{"sub":"الحصة الأولى: الشرح والعرض العملي","goals":[{"t":"أن يغير الطالب ألوان البطاقة بما يتناسب مع محتواها.","d":"مهاري","l":"معالجة"},{"t":"أن يذكر الطالب معيارين لاختيار الألوان المناسبة.","d":"معرفي","l":"فهم"}],"items":[{"c":"التمهيد: ما اللون المناسب لبطاقة عيد؟ وهل تصلح كل الألوان للبطاقة نفسها؟","t":"يطرح على الطلاب السؤال: «ما اللون المناسب لبطاقة عيد؟ وهل تصلح كل الألوان للبطاقة نفسها؟» ويستمع لإجاباتهم، ثم يربطها بموضوع الدرس: تعديل ألوان المنشور.","l":"يجيب عن السؤال ويذكر ما يعرفه سابقاً ويتوقع موضوع الدرس.","w":2,"s":"الحوار والمناقشة"},{"c":"• من تبويب «تصميم الصفحة» نختار «نظام الألوان»\n• معاينة عدة أنظمة ألوان واختيار الأنسب لمحتوى البطاقة\n• مراعاة وضوح النص فوق لون الخلفية وتجنب الألوان المتقاربة","t":"يشرح النقاط المذكورة بالتتابع مستعيناً بالعرض العملي: يغيّر المعلم نظام ألوان البطاقة عدة مرات ويناقش مع الطلاب أيّها أنسب ولماذا.","l":"يتابع الشرح والعرض ويدوّن الملاحظات ويشارك بالأسئلة والأمثلة، وينفذ الخطوة بعد المعلم حيثما أمكن.","w":4,"s":"العرض والتطبيق الفردي"},{"c":"أسئلة التثبيت:\n• من أين نغيّر ألوان المنشور؟\n• ماذا نراعي عند اختيار الألوان؟\n• لماذا نتجنب الألوان المتقاربة؟","t":"يطرح أسئلة التثبيت ويمرّ على الطلاب لمتابعة فهمهم وتصحيح الأخطاء، ثم يلخص أهم ما جاء في الدرس.","l":"يجيب عن الأسئلة ويلخص ما تعلمه بأسلوبه.","w":3,"s":"الأسئلة والأجوبة"}],"res":"الحاسوب – برنامج الناشر – نماذج تطبيقية","ev":"التقويم: تقويم تنسيق الألوان\nالواجب البيتي: كتابة لونين مناسبين لبطاقة نجاح ولونين لبطاقة شكر"},{"sub":"الحصة الثانية: التطبيق والتدريب","goals":[{"t":"أن يغيّر الطالب نظام ألوان البطاقة بصورة صحيحة.","d":"مهاري","l":"إتقان"},{"t":"أن يقدّر الطالب أهمية التناسق في التصميم.","d":"وجداني","l":"تقدير"}],"items":[{"c":"مراجعة سريعة لدرس الحصة السابقة:\n• من تبويب «تصميم الصفحة» نختار «نظام الألوان»\n• أسئلة المراجعة: من أين نغيّر ألوان المنشور؟ — ماذا نراعي عند اختيار الألوان؟","t":"يطرح أسئلة سريعة لاسترجاع ما سبق، ويصحح المفاهيم الخاطئة قبل البدء بالتطبيق.","l":"يتذكر ما تعلمه ويجيب ويصحح فهمه.","w":2,"s":"الأسئلة والأجوبة"},{"c":"المهمة التطبيقية: يغيّر الطالب نظام ألوان بطاقته إلى ما يناسب مناسبتها ويتأكد من وضوح النص، ثم يبرر اختياره أمام زميله.","t":"يوزع المهمة ويوضح معيار النجاح، ثم يتجول بين الطلاب للتوجيه ومعالجة الأخطاء الفردية.","l":"ينفذ المهمة بنفسه خطوة بخطوة، ويطلب المساعدة عند الحاجة.","w":4,"s":"التعلم بالممارسة"},{"c":"عرض عينات من أعمال الطلاب ومناقشتها وتقويمها وفق معيار النجاح.","t":"يختار نماذج من أعمال الطلاب ويناقشها مع الصف، ويسجل ملاحظات الأداء ويعالج الأخطاء الشائعة.","l":"يعرض عمله ويستمع إلى التغذية الراجعة ويصحح أخطاءه.","w":3,"s":"التقويم الذاتي والتغذية الراجعة"}],"res":"الحاسوب – برنامج الناشر – نماذج تطبيقية","ev":"التقويم: تقويم تنسيق الألوان\nالواجب البيتي: تلوين مخطط بطاقة بألوان متناسقة"}]},{"t":"حفظ بطاقة الناشر","pl":{"goal":"أن يحفظ الطالب البطاقة باسم مناسب وفي موقع محدد.","res":"الحاسوب – برنامج الناشر – ملفات تدريبية","str":"التعلم بالممارسة / التطبيق العملي","ev":"حفظ الملف / والتحقق منه"},"s":[{"sub":"الحصة الأولى: الشرح والعرض العملي","goals":[{"t":"أن يحفظ الطالب البطاقة باسم مناسب وفي موقع محدد.","d":"مهاري","l":"معالجة"},{"t":"أن يرتب الطالب خطوات حفظ الملف ترتيباً صحيحاً.","d":"معرفي","l":"فهم"}],"items":[{"c":"التمهيد: ماذا يحدث لبطاقتنا الجميلة إذا أغلقنا الحاسوب دون حفظها؟","t":"يطرح على الطلاب السؤال: «ماذا يحدث لبطاقتنا الجميلة إذا أغلقنا الحاسوب دون حفظها؟» ويستمع لإجاباتهم، ثم يربطها بموضوع الدرس: حفظ بطاقة الناشر.","l":"يجيب عن السؤال ويذكر ما يعرفه سابقاً ويتوقع موضوع الدرس.","w":2,"s":"الحوار والمناقشة"},{"c":"• قائمة «ملف» ثم «حفظ باسم» ثم اختيار الموقع (مجلد المستندات أو سطح المكتب)\n• كتابة اسم مناسب يدل على البطاقة ثم «حفظ»\n• التحقق: إغلاق الملف ثم فتحه من الموقع نفسه","t":"يشرح النقاط المذكورة بالتتابع مستعيناً بالعرض العملي: يحفظ المعلم بطاقة بالخطوات الصحيحة، ثم يغلقها ويفتحها من موقع الحفظ ليتأكد الطلاب من وجودها.","l":"يتابع الشرح والعرض ويدوّن الملاحظات ويشارك بالأسئلة والأمثلة، وينفذ الخطوة بعد المعلم حيثما أمكن.","w":4,"s":"التعلم بالممارسة"},{"c":"أسئلة التثبيت:\n• ما الأمر الذي نحفظ به لأول مرة؟\n• لماذا نختار اسماً واضحاً للملف؟\n• كيف نتأكد أن الملف حُفظ؟","t":"يطرح أسئلة التثبيت ويمرّ على الطلاب لمتابعة فهمهم وتصحيح الأخطاء، ثم يلخص أهم ما جاء في الدرس.","l":"يجيب عن الأسئلة ويلخص ما تعلمه بأسلوبه.","w":3,"s":"الأسئلة والأجوبة"}],"res":"الحاسوب – برنامج الناشر – ملفات تدريبية","ev":"التقويم: حفظ الملف / والتحقق منه\nالواجب البيتي: كتابة خطوات الحفظ مرتبة في الدفتر"},{"sub":"الحصة الثانية: التطبيق والتدريب","goals":[{"t":"أن يحفظ الطالب بطاقته باسم مناسب وفي موقع محدد.","d":"مهاري","l":"إتقان"},{"t":"أن يحافظ الطالب على أعماله ولا يتركها دون حفظ.","d":"وجداني","l":"استجابة"}],"items":[{"c":"مراجعة سريعة لدرس الحصة السابقة:\n• قائمة «ملف» ثم «حفظ باسم» ثم اختيار الموقع (مجلد المستندات أو سطح المكتب)\n• أسئلة المراجعة: ما الأمر الذي نحفظ به لأول مرة؟ — لماذا نختار اسماً واضحاً للملف؟","t":"يطرح أسئلة سريعة لاسترجاع ما سبق، ويصحح المفاهيم الخاطئة قبل البدء بالتطبيق.","l":"يتذكر ما تعلمه ويجيب ويصحح فهمه.","w":2,"s":"الأسئلة والأجوبة"},{"c":"المهمة التطبيقية: يحفظ الطالب بطاقته باسم يتضمن اسمه (مثال: بطاقة_اسمك) في الموقع المحدد، ثم يغلقها ويفتحها للتحقق.","t":"يوزع المهمة ويوضح معيار النجاح، ثم يتجول بين الطلاب للتوجيه ومعالجة الأخطاء الفردية.","l":"ينفذ المهمة بنفسه خطوة بخطوة، ويطلب المساعدة عند الحاجة.","w":4,"s":"التطبيق العملي"},{"c":"عرض عينات من أعمال الطلاب ومناقشتها وتقويمها وفق معيار النجاح.","t":"يختار نماذج من أعمال الطلاب ويناقشها مع الصف، ويسجل ملاحظات الأداء ويعالج الأخطاء الشائعة.","l":"يعرض عمله ويستمع إلى التغذية الراجعة ويصحح أخطاءه.","w":3,"s":"التقويم الذاتي والتغذية الراجعة"}],"res":"الحاسوب – برنامج الناشر – ملفات تدريبية","ev":"التقويم: حفظ الملف / والتحقق منه\nالواجب البيتي: كتابة ثلاثة أسماء مناسبة لملفات بطاقات"}]},{"t":"مراجعة الوحدة الرابعة وتقويمها","pl":{"goal":"أن ينشئ الطالب بطاقة متكاملة وينفذ المهارات السابقة.","res":"الحاسوب – الكتاب – نماذج بطاقات","str":"المشروع العملي / المراجعة","ev":"تقويم عملي"},"s":[{"sub":"الحصة الأولى: المراجعة","goals":[{"t":"أن ينشئ الطالب بطاقة متكاملة وينفذ المهارات السابقة.","d":"مهاري","l":"إتقان"},{"t":"أن يسترجع الطالب مراحل صنع بطاقة من الفتح إلى الحفظ.","d":"معرفي","l":"تذكر"}],"items":[{"c":"التمهيد: من يذكر لنا مراحل صنع البطاقة التي تعلمناها من الفتح حتى الحفظ؟","t":"يطرح السؤال: «من يذكر لنا مراحل صنع البطاقة التي تعلمناها من الفتح حتى الحفظ؟» ويستعرض مع الطلاب خريطة المحتوى المراد مراجعته.","l":"يشارك بالإجابة ويسترجع ما تعلمه.","w":2,"s":"الحوار والمناقشة"},{"c":"نقاط المراجعة:\n• فتح الناشر واختيار قالب بطاقة\n• كتابة النص وتنسيقه وترتيب العناصر\n• تعديل الألوان\n• حفظ الملف باسم مناسب","t":"يراجع النقاط بالتتابع، ثم ينفذ النشاط التالي: يعرض المعلم نموذجاً لبطاقة متكاملة ويوزع قائمة معايير التقويم (نص، ترتيب، ألوان، حفظ) ليتعرف الطلاب على ما سيقوَّمون به.","l":"يشارك في المراجعة ويحل الأنشطة ويسجل ما يحتاج إلى معالجة.","w":4,"s":"المشروع العملي"},{"c":"أسئلة المراجعة:\n• ما أول خطوة في إنشاء البطاقة؟\n• كيف نغيّر ألوانها؟\n• كيف نحفظها؟","t":"يطرح أسئلة المراجعة ويصحح الإجابات ويحدد نقاط الضعف لمعالجتها.","l":"يجيب عن الأسئلة ويدوّن أخطاءه لمعالجتها.","w":3,"s":"الأسئلة والأجوبة"}],"res":"الحاسوب – الكتاب – نماذج بطاقات","ev":"التقويم: تقويم عملي\nالواجب البيتي: مراجعة خطوات الوحدة الرابعة من الكتاب"},{"sub":"الحصة الثانية: التقويم التطبيقي","goals":[{"t":"أن ينجز الطالب بطاقة متكاملة وفق معايير التقويم.","d":"مهاري","l":"إتقان"},{"t":"أن يقيّم الطالب عمله وعمل زميله بأدب وموضوعية.","d":"وجداني","l":"تقدير"}],"items":[{"c":"مراجعة موجزة لأهم النقاط وتوضيح معايير التقويم.","t":"يذكّر الطلاب بأهم النقاط ويوضح معايير التقويم وزمنه.","l":"يستمع لمعايير التقويم ويستعد للتنفيذ.","w":2,"s":"الشرح الموجز"},{"c":"مشروع عملي: ينشئ الطالب بطاقة متكاملة لمناسبة يختارها (فتح، قالب، نص منسق، ألوان مناسبة، حفظ باسم مناسب) ويعرضها.","t":"يوزع المهمة أو ورقة الأسئلة ويراقب التنفيذ، ويسجل الدرجات وملاحظات الأداء.","l":"ينفذ المهمة بنفسه ويلتزم بالوقت والتعليمات.","w":4,"s":"المراجعة"},{"c":"مناقشة النتائج ومعالجة جوانب الضعف.","t":"يناقش النتائج مع الطلاب، ويقدم تغذية راجعة فردية ويحدد من يحتاج إلى تدريب علاجي.","l":"يستمع إلى التغذية الراجعة ويصحح أخطاءه ويحدد ما يحتاج إلى تحسين.","w":3,"s":"التقويم الذاتي والتغذية الراجعة"}],"res":"الحاسوب – الكتاب – نماذج بطاقات","ev":"التقويم: تقويم عملي\nالواجب البيتي: استكمال تصميم البطاقة إن لم تكتمل"}]},{"t":"مراجعة عامة للوحدتين الثالثة والرابعة","pl":{"goal":"أن يربط الطالب بين مهارات معالجة النصوص والنشر.","res":"الحاسوب – أوراق العمل","str":"التعلم التعاوني / الأسئلة والأجوبة","ev":"أسئلة ومهام تطبيقية"},"s":[{"sub":"الحصة الأولى: المراجعة","goals":[{"t":"أن يربط الطالب بين مهارات معالجة النصوص والنشر.","d":"معرفي","l":"تحليل"},{"t":"أن يقارن الطالب بين برنامجي Word وPublisher من حيث الاستخدام.","d":"معرفي","l":"تحليل"}],"items":[{"c":"التمهيد: ما الشيء المشترك بين Word وPublisher؟ وما الذي يختلف بينهما؟","t":"يطرح السؤال: «ما الشيء المشترك بين Word وPublisher؟ وما الذي يختلف بينهما؟» ويستعرض مع الطلاب خريطة المحتوى المراد مراجعته.","l":"يشارك بالإجابة ويسترجع ما تعلمه.","w":2,"s":"الحوار والمناقشة"},{"c":"نقاط المراجعة:\n• المشترك: الكتابة والتنسيق وإدراج الصور والحفظ\n• المختلف: Word للمستندات والتقارير وPublisher للبطاقات والمنشورات\n• متى نستخدم كل برنامج","t":"يراجع النقاط بالتتابع، ثم ينفذ النشاط التالي: يقسّم المعلم الطلاب إلى مجموعات لحل بطاقات أسئلة متنوعة، ثم يناقش الإجابات ويصحح المفاهيم الخاطئة.","l":"يشارك في المراجعة ويحل الأنشطة ويسجل ما يحتاج إلى معالجة.","w":4,"s":"التعلم التعاوني"},{"c":"أسئلة المراجعة:\n• متى نختار Word؟ ومتى نختار Publisher؟\n• اذكر أداة تنسيق مشتركة بين البرنامجين.\n• كيف نحفظ العمل في أي منهما؟","t":"يطرح أسئلة المراجعة ويصحح الإجابات ويحدد نقاط الضعف لمعالجتها.","l":"يجيب عن الأسئلة ويدوّن أخطاءه لمعالجتها.","w":3,"s":"الأسئلة والأجوبة"}],"res":"الحاسوب – أوراق العمل","ev":"التقويم: أسئلة ومهام تطبيقية\nالواجب البيتي: إعداد جدول صغير: وجه الشبه والاختلاف بين Word وPublisher"},{"sub":"الحصة الثانية: التقويم التطبيقي","goals":[{"t":"أن ينفذ الطالب مهام متتابعة في البرنامجين بسلاسة.","d":"مهاري","l":"إتقان"},{"t":"أن يتعاون الطالب مع مجموعته في حل الأنشطة.","d":"وجداني","l":"استجابة"}],"items":[{"c":"مراجعة موجزة لأهم النقاط وتوضيح معايير التقويم.","t":"يذكّر الطلاب بأهم النقاط ويوضح معايير التقويم وزمنه.","l":"يستمع لمعايير التقويم ويستعد للتنفيذ.","w":2,"s":"الشرح الموجز"},{"c":"مهمة تطبيقية: ينفذ الطالب مهمتين متتاليتين: مستند Word قصير منسق، ثم بطاقة في الناشر لمناسبة يختارها.","t":"يوزع المهمة أو ورقة الأسئلة ويراقب التنفيذ، ويسجل الدرجات وملاحظات الأداء.","l":"ينفذ المهمة بنفسه ويلتزم بالوقت والتعليمات.","w":4,"s":"الأسئلة والأجوبة"},{"c":"مناقشة النتائج ومعالجة جوانب الضعف.","t":"يناقش النتائج مع الطلاب، ويقدم تغذية راجعة فردية ويحدد من يحتاج إلى تدريب علاجي.","l":"يستمع إلى التغذية الراجعة ويصحح أخطاءه ويحدد ما يحتاج إلى تحسين.","w":3,"s":"التقويم الذاتي والتغذية الراجعة"}],"res":"الحاسوب – أوراق العمل","ev":"التقويم: أسئلة ومهام تطبيقية\nالواجب البيتي: مراجعة الأسئلة التي أخطأنا فيها"}]},{"t":"التقويم الختامي ومعالجة جوانب الضعف","pl":{"goal":"أن يظهر الطالب مدى إتقانه للمهارات المقررة.","res":"الحاسوب – نماذج تقويم","str":"التقويم الفردي / التدريب العلاجي","ev":"اختبار نظري وعملي"},"s":[{"sub":"الحصة الأولى: المراجعة الشاملة","goals":[{"t":"أن يظهر الطالب مدى إتقانه للمهارات المقررة.","d":"معرفي","l":"تطبيق"},{"t":"أن يجيب الطالب عن أسئلة الاختبار النظري بدقة.","d":"معرفي","l":"تطبيق"}],"items":[{"c":"التمهيد: كيف نستعد معاً لاختبار نظري وعملي في كل ما تعلمناه هذا الفصل؟","t":"يطرح السؤال: «كيف نستعد معاً لاختبار نظري وعملي في كل ما تعلمناه هذا الفصل؟» ويستعرض مع الطلاب خريطة المحتوى المراد مراجعته.","l":"يشارك بالإجابة ويسترجع ما تعلمه.","w":2,"s":"الحوار والمناقشة"},{"c":"نقاط المراجعة:\n• مراجعة أهم مفاهيم Word: الواجهة والكتابة والتنسيق والصور\n• مراجعة أهم مهارات Publisher: القالب والنص والألوان والحفظ\n• شرح طريقة الاختبار وزمنه ومعايير التقدير","t":"يراجع النقاط بالتتابع، ثم ينفذ النشاط التالي: يعرض المعلم نموذجاً لأسئلة الاختبار ويراجع معهم الأخطاء الشائعة التي لاحظها خلال الفصل.","l":"يشارك في المراجعة ويحل الأنشطة ويسجل ما يحتاج إلى معالجة.","w":4,"s":"التقويم الفردي"},{"c":"أسئلة المراجعة:\n• ما أخطر خطأ نقع فيه عند عدم الحفظ؟\n• ما خطوات تنسيق عنوان؟\n• كيف ننشئ بطاقة من قالب؟","t":"يطرح أسئلة المراجعة ويصحح الإجابات ويحدد نقاط الضعف لمعالجتها.","l":"يجيب عن الأسئلة ويدوّن أخطاءه لمعالجتها.","w":3,"s":"الأسئلة والأجوبة"}],"res":"الحاسوب – نماذج تقويم","ev":"التقويم: اختبار نظري وعملي\nالواجب البيتي: مراجعة نقاط الضعف التي حددها المعلم"},{"sub":"الحصة الثانية: الاختبار والتغذية الراجعة","goals":[{"t":"أن ينفذ الطالب المهمة العملية بصورة صحيحة.","d":"مهاري","l":"إتقان"},{"t":"أن يتقبل الطالب نتيجته ويضع خطة لتحسين نقاط ضعفه.","d":"وجداني","l":"تقدير"}],"items":[{"c":"مراجعة موجزة لأهم النقاط وتوضيح معايير التقويم.","t":"يذكّر الطلاب بأهم النقاط ويوضح معايير التقويم وزمنه.","l":"يستمع لمعايير التقويم ويستعد للتنفيذ.","w":2,"s":"الشرح الموجز"},{"c":"اختبار نظري (ورقة أسئلة) واختبار عملي (مهمة قصيرة على الجهاز) ثم تدريب علاجي فردي لمن أخطأ.","t":"يوزع المهمة أو ورقة الأسئلة ويراقب التنفيذ، ويسجل الدرجات وملاحظات الأداء.","l":"ينفذ المهمة بنفسه ويلتزم بالوقت والتعليمات.","w":4,"s":"التدريب العلاجي"},{"c":"مناقشة النتائج ومعالجة جوانب الضعف.","t":"يناقش النتائج مع الطلاب، ويقدم تغذية راجعة فردية ويحدد من يحتاج إلى تدريب علاجي.","l":"يستمع إلى التغذية الراجعة ويصحح أخطاءه ويحدد ما يحتاج إلى تحسين.","w":3,"s":"التقويم الذاتي والتغذية الراجعة"}],"res":"الحاسوب – نماذج تقويم","ev":"التقويم: اختبار نظري وعملي\nالواجب البيتي: إكمال التدريبات العلاجية"}]}]},"5":{"n":"الخامس الأساسي","tag":"PowerPoint","w":[{"t":"الوحدة الثالثة: مفهوم برنامج باور بوينت وتشغيله (ص 25)","pl":{"goal":"أن يتعرف الطالب على برنامج باور بوينت ويذكر استخداماته ويشغله.","res":"الحاسوب – الكتاب – جهاز العرض","str":"الشرح المبسط – العرض العملي / الحوار والمناقشة","ev":"أسئلة شفهية / وتطبيق عملي"},"s":[{"sub":"الحصة الأولى: الشرح والعرض العملي","goals":[{"t":"أن يتعرف الطالب على برنامج باور بوينت ويذكر استخداماته ويشغله.","d":"معرفي","l":"تذكر"},{"t":"أن يذكر الطالب ثلاثة استخدامات لبرنامج باور بوينت.","d":"معرفي","l":"تذكر"}],"items":[{"c":"التمهيد: عندما يعرض المعلم أو الطالب موضوعاً أمام الصف بالصور والشرائح، أي برنامج يُستخدم برأيكم؟","t":"يطرح على الطلاب السؤال: «عندما يعرض المعلم أو الطالب موضوعاً أمام الصف بالصور والشرائح، أي برنامج يُستخدم برأيكم؟» ويستمع لإجاباتهم، ثم يربطها بموضوع الدرس: الوحدة الثالثة: مفهوم برنامج باور بوينت وتشغيله (ص 25).","l":"يجيب عن السؤال ويذكر ما يعرفه سابقاً ويتوقع موضوع الدرس.","w":2,"s":"الحوار والمناقشة"},{"c":"• باور بوينت (PowerPoint) برنامج لإنشاء العروض التقديمية من شرائح تجمع النص والصور\n• استخداماته: عرض الدروس والمشاريع والتقارير وإعداد الإعلانات\n• تشغيله: قائمة ابدأ ثم PowerPoint، أو البحث عن اسمه، أو اختصاره على سطح المكتب","t":"يشرح النقاط المذكورة بالتتابع مستعيناً بالعرض العملي: يشغّل المعلم باور بوينت بطريقتين، ثم يعرض نموذج عرض جاهز على جهاز العرض ليرى الطلاب شكل الشرائح.","l":"يتابع الشرح والعرض ويدوّن الملاحظات ويشارك بالأسئلة والأمثلة، وينفذ الخطوة بعد المعلم حيثما أمكن.","w":4,"s":"الشرح المبسط – العرض العملي"},{"c":"أسئلة التثبيت:\n• ما اسم البرنامج المستخدم لإنشاء العروض التقديمية؟\n• اذكر استخدامين للبرنامج.\n• كيف نشغّل البرنامج؟","t":"يطرح أسئلة التثبيت ويمرّ على الطلاب لمتابعة فهمهم وتصحيح الأخطاء، ثم يلخص أهم ما جاء في الدرس.","l":"يجيب عن الأسئلة ويلخص ما تعلمه بأسلوبه.","w":3,"s":"الأسئلة والأجوبة"}],"res":"الحاسوب – الكتاب – جهاز العرض","ev":"التقويم: أسئلة شفهية / وتطبيق عملي\nالواجب البيتي: ذكر ثلاثة مواقف نستخدم فيها العروض التقديمية"},{"sub":"الحصة الثانية: التطبيق والتدريب","goals":[{"t":"أن يشغّل الطالب برنامج باور بوينت بطريقتين مختلفتين.","d":"مهاري","l":"تقليد"},{"t":"أن يقدّر الطالب أهمية العروض التقديمية في الدراسة.","d":"وجداني","l":"تقدير"}],"items":[{"c":"مراجعة سريعة لدرس الحصة السابقة:\n• باور بوينت (PowerPoint) برنامج لإنشاء العروض التقديمية من شرائح تجمع النص والصور\n• أسئلة المراجعة: ما اسم البرنامج المستخدم لإنشاء العروض التقديمية؟ — اذكر استخدامين للبرنامج.","t":"يطرح أسئلة سريعة لاسترجاع ما سبق، ويصحح المفاهيم الخاطئة قبل البدء بالتطبيق.","l":"يتذكر ما تعلمه ويجيب ويصحح فهمه.","w":2,"s":"الأسئلة والأجوبة"},{"c":"المهمة التطبيقية: يشغّل كل طالب البرنامج بنفسه ويفتح «عرضاً تقديمياً فارغاً» ويتصفح الشاشة الأولى ثم يغلقه.","t":"يوزع المهمة ويوضح معيار النجاح، ثم يتجول بين الطلاب للتوجيه ومعالجة الأخطاء الفردية.","l":"ينفذ المهمة بنفسه خطوة بخطوة، ويطلب المساعدة عند الحاجة.","w":4,"s":"الحوار والمناقشة"},{"c":"عرض عينات من أعمال الطلاب ومناقشتها وتقويمها وفق معيار النجاح.","t":"يختار نماذج من أعمال الطلاب ويناقشها مع الصف، ويسجل ملاحظات الأداء ويعالج الأخطاء الشائعة.","l":"يعرض عمله ويستمع إلى التغذية الراجعة ويصحح أخطاءه.","w":3,"s":"التقويم الذاتي والتغذية الراجعة"}],"res":"الحاسوب – الكتاب – جهاز العرض","ev":"التقويم: أسئلة شفهية / وتطبيق عملي\nالواجب البيتي: رسم أيقونة باور بوينت وكتابة خطوات تشغيله"}]},{"t":"مكونات نافذة باور بوينت (ص 26)","pl":{"goal":"أن يتعرف الطالب على مكونات نافذة البرنامج ويحدد وظائفها.","res":"الحاسوب – برنامج باور بوينت – السبورة","str":"المشاهدة – العرض العملي / التطبيق الفردي","ev":"تحديد المكونات / وتنفيذ الأوامر"},"s":[{"sub":"الحصة الأولى: الشرح والعرض العملي","goals":[{"t":"أن يتعرف الطالب على مكونات نافذة البرنامج ويحدد وظائفها.","d":"معرفي","l":"فهم"},{"t":"أن يسمّي الطالب أربعة مكونات على الأقل من نافذة باور بوينت.","d":"معرفي","l":"تذكر"}],"items":[{"c":"التمهيد: إذا فتحنا باور بوينت، كيف نعرف أين نضع النص وأين نجد الأدوات؟","t":"يطرح على الطلاب السؤال: «إذا فتحنا باور بوينت، كيف نعرف أين نضع النص وأين نجد الأدوات؟» ويستمع لإجاباتهم، ثم يربطها بموضوع الدرس: مكونات نافذة باور بوينت (ص 26).","l":"يجيب عن السؤال ويذكر ما يعرفه سابقاً ويتوقع موضوع الدرس.","w":2,"s":"الحوار والمناقشة"},{"c":"• شريط العنوان والشريط وعلامات التبويب: ملف، الصفحة الرئيسية، إدراج، تصميم\n• لوحة الشرائح المصغرة على جانب الشاشة ومنطقة الشريحة الرئيسية للعمل\n• منطقة الملاحظات وشريط الحالة وأزرار طرق العرض","t":"يشرح النقاط المذكورة بالتتابع مستعيناً بالعرض العملي: يحدد المعلم على الشاشة المعروضة كل مكون ويكتب اسمه على السبورة، ثم يطلب من الطلاب تحديد المكان قبل أن يشير إليه.","l":"يتابع الشرح والعرض ويدوّن الملاحظات ويشارك بالأسئلة والأمثلة، وينفذ الخطوة بعد المعلم حيثما أمكن.","w":4,"s":"المشاهدة – العرض العملي"},{"c":"أسئلة التثبيت:\n• ما الجزء الذي تظهر فيه الشرائح المصغرة؟\n• أين نكتب محتوى الشريحة؟\n• ما وظيفة علامات التبويب؟","t":"يطرح أسئلة التثبيت ويمرّ على الطلاب لمتابعة فهمهم وتصحيح الأخطاء، ثم يلخص أهم ما جاء في الدرس.","l":"يجيب عن الأسئلة ويلخص ما تعلمه بأسلوبه.","w":3,"s":"الأسئلة والأجوبة"}],"res":"الحاسوب – برنامج باور بوينت – السبورة","ev":"التقويم: تحديد المكونات / وتنفيذ الأوامر\nالواجب البيتي: رسم نافذة باور بوينت مبسطة وتسمية أربعة مكونات"},{"sub":"الحصة الثانية: التطبيق والتدريب","goals":[{"t":"أن ينفذ الطالب أوامر التنقل بين علامات التبويب بصورة صحيحة.","d":"مهاري","l":"تقليد"},{"t":"أن يتعاون الطالب مع زميله في تحديد المكونات.","d":"وجداني","l":"استجابة"}],"items":[{"c":"مراجعة سريعة لدرس الحصة السابقة:\n• شريط العنوان والشريط وعلامات التبويب: ملف، الصفحة الرئيسية، إدراج، تصميم\n• أسئلة المراجعة: ما الجزء الذي تظهر فيه الشرائح المصغرة؟ — أين نكتب محتوى الشريحة؟","t":"يطرح أسئلة سريعة لاسترجاع ما سبق، ويصحح المفاهيم الخاطئة قبل البدء بالتطبيق.","l":"يتذكر ما تعلمه ويجيب ويصحح فهمه.","w":2,"s":"الأسئلة والأجوبة"},{"c":"المهمة التطبيقية: يسمّي الطالب الأجزاء المرقمة على صورة نافذة البرنامج في ورقة العمل، ثم ينفذ على جهازه: فتح علامة تبويب «إدراج» ثم الرجوع إلى «الصفحة الرئيسية».","t":"يوزع المهمة ويوضح معيار النجاح، ثم يتجول بين الطلاب للتوجيه ومعالجة الأخطاء الفردية.","l":"ينفذ المهمة بنفسه خطوة بخطوة، ويطلب المساعدة عند الحاجة.","w":4,"s":"التطبيق الفردي"},{"c":"عرض عينات من أعمال الطلاب ومناقشتها وتقويمها وفق معيار النجاح.","t":"يختار نماذج من أعمال الطلاب ويناقشها مع الصف، ويسجل ملاحظات الأداء ويعالج الأخطاء الشائعة.","l":"يعرض عمله ويستمع إلى التغذية الراجعة ويصحح أخطاءه.","w":3,"s":"التقويم الذاتي والتغذية الراجعة"}],"res":"الحاسوب – برنامج باور بوينت – السبورة","ev":"التقويم: تحديد المكونات / وتنفيذ الأوامر\nالواجب البيتي: كتابة وظيفة ثلاثة مكونات في الدفتر"}]},{"t":"خطوات إغلاق وحفظ باور بوينت (ص 27)","pl":{"goal":"أن يغلق الطالب البرنامج ويحفظ عرضه باسم مناسب.","res":"الحاسوب – برنامج باور بوينت – الكتاب","str":"التعلم بالممارسة / حل المشكلات","ev":"تنفيذ الخطوات / وملاحظة الأداء"},"s":[{"sub":"الحصة الأولى: الشرح والعرض العملي","goals":[{"t":"أن يغلق الطالب البرنامج ويحفظ عرضه باسم مناسب.","d":"مهاري","l":"معالجة"},{"t":"أن يرتب الطالب خطوات حفظ العرض ترتيباً صحيحاً.","d":"معرفي","l":"فهم"}],"items":[{"c":"التمهيد: ماذا يحدث لعملنا إذا أغلقنا البرنامج دون حفظه؟","t":"يطرح على الطلاب السؤال: «ماذا يحدث لعملنا إذا أغلقنا البرنامج دون حفظه؟» ويستمع لإجاباتهم، ثم يربطها بموضوع الدرس: خطوات إغلاق وحفظ باور بوينت (ص 27).","l":"يجيب عن السؤال ويذكر ما يعرفه سابقاً ويتوقع موضوع الدرس.","w":2,"s":"الحوار والمناقشة"},{"c":"• حفظ العرض: ملف ثم «حفظ باسم» ثم اختيار الموقع ثم كتابة الاسم ثم «حفظ»\n• اختيار اسم مناسب يدل على المحتوى (مثل: عرض_مدرستي_اسمك)\n• إغلاق العرض ثم البرنامج، وفتح العرض المحفوظ من موقعه للتأكد","t":"يشرح النقاط المذكورة بالتتابع مستعيناً بالعرض العملي: يحفظ المعلم عرضاً بخطواته الكاملة، ثم يغلق البرنامج ويفتح الملف من موقع الحفظ.","l":"يتابع الشرح والعرض ويدوّن الملاحظات ويشارك بالأسئلة والأمثلة، وينفذ الخطوة بعد المعلم حيثما أمكن.","w":4,"s":"التعلم بالممارسة"},{"c":"أسئلة التثبيت:\n• ما أول أمر نستخدمه لحفظ عرض جديد؟\n• لماذا نختار اسماً واضحاً؟\n• كيف نتأكد أن الملف حُفظ؟","t":"يطرح أسئلة التثبيت ويمرّ على الطلاب لمتابعة فهمهم وتصحيح الأخطاء، ثم يلخص أهم ما جاء في الدرس.","l":"يجيب عن الأسئلة ويلخص ما تعلمه بأسلوبه.","w":3,"s":"الأسئلة والأجوبة"}],"res":"الحاسوب – برنامج باور بوينت – الكتاب","ev":"التقويم: تنفيذ الخطوات / وملاحظة الأداء\nالواجب البيتي: كتابة خطوات الحفظ والإغلاق مرتبة في الدفتر"},{"sub":"الحصة الثانية: التطبيق والتدريب","goals":[{"t":"أن يحفظ الطالب العرض باسم مناسب ويغلق البرنامج بطريقة سليمة.","d":"مهاري","l":"إتقان"},{"t":"أن يحافظ الطالب على أعماله ولا يتركها دون حفظ.","d":"وجداني","l":"استجابة"}],"items":[{"c":"مراجعة سريعة لدرس الحصة السابقة:\n• حفظ العرض: ملف ثم «حفظ باسم» ثم اختيار الموقع ثم كتابة الاسم ثم «حفظ»\n• أسئلة المراجعة: ما أول أمر نستخدمه لحفظ عرض جديد؟ — لماذا نختار اسماً واضحاً؟","t":"يطرح أسئلة سريعة لاسترجاع ما سبق، ويصحح المفاهيم الخاطئة قبل البدء بالتطبيق.","l":"يتذكر ما تعلمه ويجيب ويصحح فهمه.","w":2,"s":"الأسئلة والأجوبة"},{"c":"المهمة التطبيقية: يحفظ الطالب العرض الذي أنشأه باسم يتضمن اسمه، ثم يغلق البرنامج ويفتح الملف للتأكد، ثم يجرّب معالجة رسالة «هل تريد حفظ التغييرات؟».","t":"يوزع المهمة ويوضح معيار النجاح، ثم يتجول بين الطلاب للتوجيه ومعالجة الأخطاء الفردية.","l":"ينفذ المهمة بنفسه خطوة بخطوة، ويطلب المساعدة عند الحاجة.","w":4,"s":"حل المشكلات"},{"c":"عرض عينات من أعمال الطلاب ومناقشتها وتقويمها وفق معيار النجاح.","t":"يختار نماذج من أعمال الطلاب ويناقشها مع الصف، ويسجل ملاحظات الأداء ويعالج الأخطاء الشائعة.","l":"يعرض عمله ويستمع إلى التغذية الراجعة ويصحح أخطاءه.","w":3,"s":"التقويم الذاتي والتغذية الراجعة"}],"res":"الحاسوب – برنامج باور بوينت – الكتاب","ev":"التقويم: تنفيذ الخطوات / وملاحظة الأداء\nالواجب البيتي: كتابة ثلاثة أسماء مناسبة لملفات عروض"}]},{"t":"إنشاء عرض تقديمي فارغ (ص29)","pl":{"goal":"أن ينشئ الطالب عرضاً تقديمياً فارغاً ويحدد تصميمه الأساسي.","res":"الحاسوب – برنامج باور بوينت – الكتاب","str":"الشرح – العرض العملي / التطبيق الفردي","ev":"تنفيذ مهمة إنشاء عرض"},"s":[{"sub":"الحصة الأولى: الشرح والعرض العملي","goals":[{"t":"أن ينشئ الطالب عرضاً تقديمياً فارغاً ويحدد تصميمه الأساسي.","d":"مهاري","l":"معالجة"},{"t":"أن يذكر الطالب الخطوات الأساسية لإنشاء عرض فارغ.","d":"معرفي","l":"تذكر"}],"items":[{"c":"التمهيد: كيف نبدأ عرضاً جديداً عن «مدرستي» من صفحة بيضاء؟","t":"يطرح على الطلاب السؤال: «كيف نبدأ عرضاً جديداً عن «مدرستي» من صفحة بيضاء؟» ويستمع لإجاباتهم، ثم يربطها بموضوع الدرس: إنشاء عرض تقديمي فارغ (ص29).","l":"يجيب عن السؤال ويذكر ما يعرفه سابقاً ويتوقع موضوع الدرس.","w":2,"s":"الحوار والمناقشة"},{"c":"• ملف ثم «جديد» ثم «عرض تقديمي فارغ»\n• اختيار تصميم أساسي (سمة) من علامة تبويب «تصميم»\n• شريحة العنوان الأولى وأنواع التخطيطات المتاحة","t":"يشرح النقاط المذكورة بالتتابع مستعيناً بالعرض العملي: ينشئ المعلم عرضاً فارغاً ويطبق عليه تصميماً أساسياً ثم يستعرض التخطيطات المتاحة للشريحة الأولى.","l":"يتابع الشرح والعرض ويدوّن الملاحظات ويشارك بالأسئلة والأمثلة، وينفذ الخطوة بعد المعلم حيثما أمكن.","w":4,"s":"الشرح – العرض العملي"},{"c":"أسئلة التثبيت:\n• ما أول أمر لإنشاء عرض جديد؟\n• من أين نختار تصميم الشرائح؟\n• ما الشريحة التي تظهر أولاً؟","t":"يطرح أسئلة التثبيت ويمرّ على الطلاب لمتابعة فهمهم وتصحيح الأخطاء، ثم يلخص أهم ما جاء في الدرس.","l":"يجيب عن الأسئلة ويلخص ما تعلمه بأسلوبه.","w":3,"s":"الأسئلة والأجوبة"}],"res":"الحاسوب – برنامج باور بوينت – الكتاب","ev":"التقويم: تنفيذ مهمة إنشاء عرض\nالواجب البيتي: كتابة خطوات إنشاء عرض فارغ مرتبة"},{"sub":"الحصة الثانية: التطبيق والتدريب","goals":[{"t":"أن ينشئ الطالب عرضاً فارغاً ويطبق عليه تصميماً أساسياً.","d":"مهاري","l":"إتقان"},{"t":"أن يختار الطالب موضوعاً مناسباً لعرضه باهتمام.","d":"وجداني","l":"استجابة"}],"items":[{"c":"مراجعة سريعة لدرس الحصة السابقة:\n• ملف ثم «جديد» ثم «عرض تقديمي فارغ»\n• أسئلة المراجعة: ما أول أمر لإنشاء عرض جديد؟ — من أين نختار تصميم الشرائح؟","t":"يطرح أسئلة سريعة لاسترجاع ما سبق، ويصحح المفاهيم الخاطئة قبل البدء بالتطبيق.","l":"يتذكر ما تعلمه ويجيب ويصحح فهمه.","w":2,"s":"الأسئلة والأجوبة"},{"c":"المهمة التطبيقية: ينشئ الطالب عرضاً فارغاً ويختار له تصميماً مناسباً لموضوع «مدرستي» ويكتب عنوان العرض في شريحة العنوان.","t":"يوزع المهمة ويوضح معيار النجاح، ثم يتجول بين الطلاب للتوجيه ومعالجة الأخطاء الفردية.","l":"ينفذ المهمة بنفسه خطوة بخطوة، ويطلب المساعدة عند الحاجة.","w":4,"s":"التطبيق الفردي"},{"c":"عرض عينات من أعمال الطلاب ومناقشتها وتقويمها وفق معيار النجاح.","t":"يختار نماذج من أعمال الطلاب ويناقشها مع الصف، ويسجل ملاحظات الأداء ويعالج الأخطاء الشائعة.","l":"يعرض عمله ويستمع إلى التغذية الراجعة ويصحح أخطاءه.","w":3,"s":"التقويم الذاتي والتغذية الراجعة"}],"res":"الحاسوب – برنامج باور بوينت – الكتاب","ev":"التقويم: تنفيذ مهمة إنشاء عرض\nالواجب البيتي: اختيار موضوع لعرضنا (مدرستي، عائلتي، هوايتي)"}]},{"t":"إضافة شريحة نص وشريحة عنوان (ص 30)","pl":{"goal":"أن يضيف الطالب شرائح مختلفة ويستخدم شريحة نص وعنوان.","res":"الحاسوب – برنامج باور بوينت – الكتاب","str":"التعلم بالممارسة / التطبيق العملي","ev":"إدراج الشرائح / وتقييمها"},"s":[{"sub":"الحصة الأولى: الشرح والعرض العملي","goals":[{"t":"أن يضيف الطالب شرائح مختلفة ويستخدم شريحة نص وعنوان.","d":"مهاري","l":"معالجة"},{"t":"أن يميز الطالب بين شريحة العنوان وشريحة النص.","d":"معرفي","l":"فهم"}],"items":[{"c":"التمهيد: كيف نضيف شريحة جديدة بعد العنوان لنكتب فيها معلومات عن موضوعنا؟","t":"يطرح على الطلاب السؤال: «كيف نضيف شريحة جديدة بعد العنوان لنكتب فيها معلومات عن موضوعنا؟» ويستمع لإجاباتهم، ثم يربطها بموضوع الدرس: إضافة شريحة نص وشريحة عنوان (ص 30).","l":"يجيب عن السؤال ويذكر ما يعرفه سابقاً ويتوقع موضوع الدرس.","w":2,"s":"الحوار والمناقشة"},{"c":"• إضافة شريحة جديدة: علامة التبويب «الصفحة الرئيسية» ثم «شريحة جديدة»\n• اختيار تخطيط الشريحة: «شريحة عنوان» و«عنوان ومحتوى»\n• الفرق بين شريحة العنوان (الصفحة الأولى) وشريحة النص (للمحتوى)","t":"يشرح النقاط المذكورة بالتتابع مستعيناً بالعرض العملي: يضيف المعلم شريحتين بتخطيطين مختلفين ويوضح الفرق بينهما وكيف يغيّر تخطيط الشريحة بعد إضافتها.","l":"يتابع الشرح والعرض ويدوّن الملاحظات ويشارك بالأسئلة والأمثلة، وينفذ الخطوة بعد المعلم حيثما أمكن.","w":4,"s":"التعلم بالممارسة"},{"c":"أسئلة التثبيت:\n• من أين نضيف شريحة جديدة؟\n• ما الفرق بين شريحة العنوان وشريحة المحتوى؟\n• كيف نغيّر تخطيط الشريحة؟","t":"يطرح أسئلة التثبيت ويمرّ على الطلاب لمتابعة فهمهم وتصحيح الأخطاء، ثم يلخص أهم ما جاء في الدرس.","l":"يجيب عن الأسئلة ويلخص ما تعلمه بأسلوبه.","w":3,"s":"الأسئلة والأجوبة"}],"res":"الحاسوب – برنامج باور بوينت – الكتاب","ev":"التقويم: إدراج الشرائح / وتقييمها\nالواجب البيتي: رسم شريحة عنوان وشريحة نص في الدفتر مع تسمية أجزائهما"},{"sub":"الحصة الثانية: التطبيق والتدريب","goals":[{"t":"أن يضيف الطالب شرائح بتخطيطات مختلفة إلى عرضه.","d":"مهاري","l":"إتقان"},{"t":"أن يحرص الطالب على ترتيب شرائح عرضه.","d":"وجداني","l":"استجابة"}],"items":[{"c":"مراجعة سريعة لدرس الحصة السابقة:\n• إضافة شريحة جديدة: علامة التبويب «الصفحة الرئيسية» ثم «شريحة جديدة»\n• أسئلة المراجعة: من أين نضيف شريحة جديدة؟ — ما الفرق بين شريحة العنوان وشريحة المحتوى؟","t":"يطرح أسئلة سريعة لاسترجاع ما سبق، ويصحح المفاهيم الخاطئة قبل البدء بالتطبيق.","l":"يتذكر ما تعلمه ويجيب ويصحح فهمه.","w":2,"s":"الأسئلة والأجوبة"},{"c":"المهمة التطبيقية: يضيف الطالب إلى عرضه شريحة عنوان وشريحتي نص بتخطيطات مناسبة ثم يتأكد من ترتيبها في اللوحة الجانبية.","t":"يوزع المهمة ويوضح معيار النجاح، ثم يتجول بين الطلاب للتوجيه ومعالجة الأخطاء الفردية.","l":"ينفذ المهمة بنفسه خطوة بخطوة، ويطلب المساعدة عند الحاجة.","w":4,"s":"التطبيق العملي"},{"c":"عرض عينات من أعمال الطلاب ومناقشتها وتقويمها وفق معيار النجاح.","t":"يختار نماذج من أعمال الطلاب ويناقشها مع الصف، ويسجل ملاحظات الأداء ويعالج الأخطاء الشائعة.","l":"يعرض عمله ويستمع إلى التغذية الراجعة ويصحح أخطاءه.","w":3,"s":"التقويم الذاتي والتغذية الراجعة"}],"res":"الحاسوب – برنامج باور بوينت – الكتاب","ev":"التقويم: إدراج الشرائح / وتقييمها\nالواجب البيتي: كتابة عناوين ثلاث شرائح لعرضنا"}]},{"t":"الكتابة على الشرائح (ص 32)","pl":{"goal":"أن يكتب الطالب نصاً مناسباً على الشرائح ويستخدم أدوات التنسيق.","res":"الحاسوب – برنامج باور بوينت – الكتاب","str":"العرض العملي / المهام الفردية","ev":"مراجعة شاملة / وتقويم عملي ونظري"},"s":[{"sub":"الحصة الأولى: الشرح والعرض العملي","goals":[{"t":"أن يكتب الطالب نصاً مناسباً على الشرائح ويستخدم أدوات التنسيق.","d":"مهاري","l":"معالجة"},{"t":"أن يعلّل الطالب أهمية اختصار النص في الشريحة.","d":"معرفي","l":"فهم"}],"items":[{"c":"التمهيد: لماذا نكتب نقاطاً قصيرة على الشريحة ولا نكتب فيها فقرات طويلة؟","t":"يطرح على الطلاب السؤال: «لماذا نكتب نقاطاً قصيرة على الشريحة ولا نكتب فيها فقرات طويلة؟» ويستمع لإجاباتهم، ثم يربطها بموضوع الدرس: الكتابة على الشرائح (ص 32).","l":"يجيب عن السؤال ويذكر ما يعرفه سابقاً ويتوقع موضوع الدرس.","w":2,"s":"الحوار والمناقشة"},{"c":"• النقر داخل مربع النص وكتابة العنوان والنقاط\n• تنسيق النص: الخط والحجم واللون والمحاذاة كما في Word\n• كتابة نقاط مختصرة وواضحة وعدم الإكثار من الكلام في الشريحة الواحدة","t":"يشرح النقاط المذكورة بالتتابع مستعيناً بالعرض العملي: يكتب المعلم عنواناً ونقطتين في شريحة ثم ينسقهما، ويقارن بين شريحة مزدحمة وأخرى منظمة.","l":"يتابع الشرح والعرض ويدوّن الملاحظات ويشارك بالأسئلة والأمثلة، وينفذ الخطوة بعد المعلم حيثما أمكن.","w":4,"s":"العرض العملي"},{"c":"أسئلة التثبيت:\n• كيف نكتب داخل الشريحة؟\n• كم نقطة مناسبة في الشريحة الواحدة؟\n• ما فائدة تنسيق النص؟","t":"يطرح أسئلة التثبيت ويمرّ على الطلاب لمتابعة فهمهم وتصحيح الأخطاء، ثم يلخص أهم ما جاء في الدرس.","l":"يجيب عن الأسئلة ويلخص ما تعلمه بأسلوبه.","w":3,"s":"الأسئلة والأجوبة"}],"res":"الحاسوب – برنامج باور بوينت – الكتاب","ev":"التقويم: مراجعة شاملة / وتقويم عملي ونظري\nالواجب البيتي: كتابة ثلاث نقاط مختصرة عن موضوع عرضنا في الدفتر"},{"sub":"الحصة الثانية: التطبيق والتدريب","goals":[{"t":"أن يكتب الطالب نصاً مختصراً وينسقه تنسيقاً مقروءاً.","d":"مهاري","l":"إتقان"},{"t":"أن يتقبل الطالب ملاحظات زملائه على شرائحه.","d":"وجداني","l":"استجابة"}],"items":[{"c":"مراجعة سريعة لدرس الحصة السابقة:\n• النقر داخل مربع النص وكتابة العنوان والنقاط\n• أسئلة المراجعة: كيف نكتب داخل الشريحة؟ — كم نقطة مناسبة في الشريحة الواحدة؟",